def f(inp):
    H,W=len(inp),len(inp[0]); out=[r[:] for r in inp]
    twos=[(i,j) for i in range(H) for j,x in enumerate(inp[i]) if x==2]
    rs=[i for i,_ in twos]; cs=[j for _,j in twos]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    band=set(range(r0,r1+1))
    mrow={i:[j for j in range(W) if inp[i][j]!=0 and not(c0<=j<=c1)] for i in range(H)}
    # vertical growth: does the block extend one row in any direction it has NO neighboring markers beyond? 
    # Empirical observation demo1: grew up one row. Keep simple: extend band top by 1 if markers exist above band? None in demo1... skip.
    # Full-fill band rows without markers when other marker rows exist in band
    markrows=sorted(i for i,ms in mrow.items() if ms and i in band)
    for i in band:
        ms=mrow[i]
        if ms:
            L=[m for m in ms if m<c0]; R=[m for m in ms if m>c1]
            if L and not R: rng=range(c1+1,W)
            elif R and not L: rng=range(0,c0)
            else: continue
            for j in rng: out[i][j]=2
        elif markrows and i!=markrows[0] and i!=markrows[-1]:
            for j in range(W): out[i][j]=2
    # vertical complement-lines above/below band
    topp=[(i,j) for i in range(0,r0) for j,x in enumerate(inp[i]) if x!=0 and not(c0<=j<=c1)]
    bott=[(i,j) for i in range(r1+1,H) for j,x in enumerate(inp[i]) if x!=0 and not(c0<=j<=c1)]
    w=c1-c0+1
    if topp:
        trel={j-c0 for _,j in topp}; cols=[j for j in range(c0,c1+1) if (j-c0) not in trel]
        for i in range(0,r0):
            for j in cols: out[i][j]=2
    if bott:
        brel={j-c0 for _,j in bott}; cols=[j for j in range(c0,c1+1) if (j-c0) not in brel]
        for i in range(r1+1,H):
            for j in cols: out[i][j]=2
    return out

