def f(inp):
    g=[r[:] for r in inp]; H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bandc=cnt.most_common(1)[0][0]
    # markers: nonzero, not band color... but demo2 marker=3 and band=2, fine; use rarest nonzero? just take cells != bandc and !=0
    markers=[(i,j,g[i][j]) for i in range(H) for j in range(W) if g[i][j]!=bandc and g[i][j]!=0]
    pos=[(i,j) for i in range(H) for j in range(W) if g[i][j]==bandc]
    rs=[p[0] for p in pos]; cs=[p[1] for p in pos]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    hgt=c1-c0+1
    above=[(i,j) for i,j,_ in markers if i<r0]
    below=[(i,j) for i,j,_ in markers if i>r1]
    def stripe_cols(src):
        rel={ (j-c0) for _,j,_ in src }
        return sorted(set(range(hgt))-rel)
    for i in range(0,r0):
        if above:
            for cj in stripe_cols(above): g[i][c0+cj]=bandc
    for i in range(r1+1,H):
        if below:
            for cj in stripe_cols(below): g[i][c0+cj]=bandc
    for i in range(r0,r1+1):
        lftm=[j for a,j,_ in markers if a==i and j<c0]
        rghtm=[j for a,j,_ in markers if a==i and j>c1]
        if lftm and not rghtm:
            for j in range(c1+1,W): g[i][j]=bandc
        elif rghtm and not lftm:
            for j in range(0,c0): g[i][j]=bandc
        elif lftm and rghtm:
            for j in range(0,c0): g[i][j]=bandc
            for j in range(c1+1,W): g[i][j]=bandc
        else:
            for j in range(W): g[i][j]=bandc
    return g
