G=load(); print(sorted(G))

def f(inp):
    import numpy as np
    g=np.array(inp); H,W=g.shape
    vals,counts=np.unique(g,return_counts=True)
    bandc=int(vals[np.argmax(counts)])
    mc=[int(v) for v,c in zip(vals,counts) if c==counts.min()]
    mk=set(int(v) for v in mc)
    bmask=(g==bandc)
    rs,cs=np.where(bmask)
    r0,r1,c0,c1=rs.min(),rs.max(),cs.min(),cs.max()
    out=g.copy()
    # markers grouped by side
    left=[(i,j) for i,j in zip(*np.where(g!=bandc&~np.zeros_like(g,bool))) ] if False else [(i,j) for i in range(H) for j in range(W) if g[i][j]!=bandc and g[i][j]!=0 and j<c0]
    right=[(i,j) for i in range(H) for j in range(W) if g[i][j]!=bandc and g[i][j]!=0 and j>c1]
    up=[(i,j) for i in range(H) for j in range(W) if g[i][j]!=bandc and g[i][j]!=0 and i<r0]
    down=[(i,j) for i in range(H) for j in range(W) if g[i][j]!=bandc and g[i][j]!=0 and i>r1]
    def fill(rows, cols, val):
        for i,j in rows:
            for jj in cols:
                if out[i][jj]==0: out[i][jj]=val
    # left side: markers give rows; fill rows NOT in marker rows, cols 0..c0-1
    mr={i for i,j in left}
    for i in range(r0,r1+1):
        if i not in mr:
            for j in range(0,c0):
                if out[i][j]==0: out[i][j]=bandc
    # right side similarly
    rr={i for i,j in right}
    for i in range(r0,r1+1):
        if i not in rr:
            for j in range(c1+1,W):
                if out[i][j]==0: out[i][j]=bandc
    # up: marker cols; fill cols NOT in marker cols, rows 0..r0-1
    mc_set={j for i,j in up}
    for j in range(c0,c1+1):
        if j not in mc_set:
            for i in range(0,r0):
                if out[i][j]==0: out[i][j]=bandc
    # down
    dc={j for i,j in down}
    for j in range(c0,c1+1):
        if j not in dc:
            for i in range(r1+1,H):
                if out[i][j]==0: out[i][j]=bandc
    return out.tolist()

